/* Son Son II sound data tables generated by tools/ss2/sound/extract.py
 * (src/ss2_sound_data.c).  See docs/ss2/SOUND.md. */
#ifndef SS2_SOUND_DATA_H
#define SS2_SOUND_DATA_H

#include "ss2_sound_seq.h"

/* YM2612 algorithm-7 additive approximation of one 32-sample PCE wave:
 * four sine carriers at harmonic MUL[i] with base attenuation TL[i]
 * (0.75 dB units, 127 = silent operator). */
typedef struct
{
    u8 mul[4];
    u8 tl[4];
} Ss2FmPatch;

extern const u16 ss2_snd_patch_count;
extern const u16 ss2_snd_wave_src[];     /* PCE wave address -> patch index */
extern const Ss2FmPatch ss2_snd_patch[];

#endif
